import {ControlGroup} from '@github-ui/control-group'
import type {Mode} from '@github-ui/control-group'
import type {PickerRepository} from '@github-ui/repos-picker'
import {modes} from '@github-ui/repos-picker/modes'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {Banner, Heading} from '@primer/react'
import {useState} from 'react'

type SelectionMode = 'all_repos' | 'no_policy' | 'multiple' | 'no_repos'
type SettingType = 'approval' | 'qualified_approval'

interface ModeOption {
  name: SelectionMode
  label: string
  description: string
}

interface CodeReviewSetting {
  callbackPath: string
  description: string
  mode: SelectionMode
  modeOptions: ModeOption[]
  repositorySelectionDescription: string
  repositorySelectionTitle: string
  selection: PickerRepository[]
  settingType: SettingType
  title: string
}

export interface CopilotCodeReviewSettingsProps {
  orgLogin: string
  settings: CodeReviewSetting[]
}

export function CopilotCodeReviewSettings({orgLogin, settings}: CopilotCodeReviewSettingsProps) {
  return (
    <div className="d-flex flex-column gap-4">
      <Heading as="h2" className="sr-only">
        Copilot code review settings
      </Heading>

      {settings.map(setting => (
        <CodeReviewSettingControl key={setting.settingType} orgLogin={orgLogin} setting={setting} />
      ))}
    </div>
  )
}

function CodeReviewSettingControl({orgLogin, setting}: {orgLogin: string; setting: CodeReviewSetting}) {
  const [mode, setMode] = useState<SelectionMode>(setting.mode)
  const [selected, setSelected] = useState<PickerRepository[]>(setting.selection)
  const [isErrorBannerShown, setIsErrorBannerShown] = useState(false)

  const updateSetting = async (body: Record<string, unknown>) => {
    const response = await reactFetchJSON(setting.callbackPath, {
      method: 'PUT',
      body: {
        setting_type: setting.settingType,
        ...body,
      },
    })

    if (!response.ok) {
      throw new Error('Failed to update setting')
    }
  }

  const onSelectionChange = async (repos: PickerRepository[]) => {
    setIsErrorBannerShown(false)
    const originalSelection = selected

    try {
      setSelected(repos)
      await updateSetting({
        mode: 'multiple',
        selected_repos: repos.map(repo => repo.id),
      })
    } catch {
      setIsErrorBannerShown(true)
      setSelected(originalSelection)
    }
  }

  const onModeChange = async (newMode: string) => {
    setIsErrorBannerShown(false)

    const originalMode = mode
    const originalSelection = selected
    const selectionMode = newMode as SelectionMode

    try {
      setMode(selectionMode)
      if (selectionMode !== 'multiple') {
        setSelected([])
      }

      await updateSetting({mode: selectionMode})
    } catch {
      setIsErrorBannerShown(true)
      setMode(originalMode)
      setSelected(originalSelection)
    }
  }

  const supportedModes = buildModes({
    modeOptions: setting.modeOptions,
    onSelectionChange,
    orgLogin,
    repositorySelectionDescription: setting.repositorySelectionDescription,
    repositorySelectionTitle: setting.repositorySelectionTitle,
    selected,
  })

  return (
    <>
      {isErrorBannerShown && (
        <Banner
          variant="critical"
          title="Failed to save changes"
          hideTitle
          className="tmp-mb-3"
          onDismiss={() => {
            setIsErrorBannerShown(false)
          }}
        >
          Failed to update setting, please try again later.
        </Banner>
      )}

      <ControlGroup className="borderColor-default px-1">
        <ControlGroup.Selector
          selectedMode={mode}
          onModeChange={onModeChange}
          modes={supportedModes}
          title={setting.title}
          description={setting.description}
        />
      </ControlGroup>
    </>
  )
}

function buildModes({
  modeOptions,
  onSelectionChange,
  orgLogin,
  repositorySelectionDescription,
  repositorySelectionTitle,
  selected,
}: {
  modeOptions: ModeOption[]
  onSelectionChange: (repos: PickerRepository[]) => Promise<void>
  orgLogin: string
  repositorySelectionDescription: string
  repositorySelectionTitle: string
  selected: PickerRepository[]
}): Mode[] {
  return modeOptions.map(option => {
    if (option.name === 'multiple') {
      return {
        ...modes.buildMultiple({
          selected,
          onSubmit: onSelectionChange,
          scope: {type: 'organization', slug: orgLogin},
        }),
        name: option.name,
        label: option.label,
        description: option.description,
        editorLabel: repositorySelectionTitle,
        editorDescription: repositorySelectionDescription,
      }
    }

    if (option.name === 'all_repos') {
      return {
        ...modes.all,
        name: option.name,
        label: option.label,
        description: option.description,
      }
    }

    return {
      name: option.name,
      label: option.label,
      description: option.description,
    }
  })
}
